// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type GraphWalkProps = Record<string, any>;

// Path 1 (Downward / Market drops)
const GRAPH_POINTS_1 = [
  { x: 0.0, y: 0.2 },   // Starts low (20%)
  { x: 0.33, y: 0.7 },  // Climbs to a peak (70%)
  { x: 0.5, y: 0.45 },  // Drops
  { x: 0.68, y: 0.2 },  // Continues down
  { x: 0.85, y: 0.08 }, // Softening
  { x: 1.0, y: 0.0 },   // End (0%)
];

// Path 2 (Protected / Goes flat at the peak, then climbs further up)
const GRAPH_POINTS_2 = [
  { x: 0.0, y: 0.2 },   // Starts low (20%)
  { x: 0.33, y: 0.7 },  // Climbs to the same peak (70%)
  { x: 0.55, y: 0.7 },  // Goes flat instead of dipping
  { x: 0.75, y: 0.7 },  // Levels out at the peak
  { x: 1.0, y: 0.9 },   // Climbs further up (90%)
];

// Helper to interpolate Y and calculate slope on the path given an X coordinate
const getPathDataAtX = (targetX: number, screenPoints: { x: number; y: number }[]) => {
  if (targetX <= screenPoints[0].x) return { y: screenPoints[0].y, slope: 0 };
  if (targetX >= screenPoints[screenPoints.length - 1].x) {
    return { y: screenPoints[screenPoints.length - 1].y, slope: 0 };
  }

  for (let i = 0; i < screenPoints.length - 1; i++) {
    const p1 = screenPoints[i];
    const p2 = screenPoints[i + 1];
    if (targetX >= p1.x && targetX <= p2.x) {
      const progress = (targetX - p1.x) / (p2.x - p1.x);
      const y = p1.y + progress * (p2.y - p1.y);
      const dx = p2.x - p1.x;
      const dy = p2.y - p1.y;
      const slope = Math.atan2(dy, dx); // in radians
      return { y, slope };
    }
  }
  return { y: 0, slope: 0 };
};

const Limb: React.FC<{
  rotation: number; // degrees
  length: number;
  thickness: number;
  color: string;
}> = ({ rotation, length, thickness, color }) => (
  <line
    x1={0}
    y1={0}
    x2={0}
    y2={length}
    stroke={color}
    strokeWidth={thickness}
    strokeLinecap="round"
    transform={`rotate(${rotation})`}
  />
);

const GraphWalk: React.FC<GraphWalkProps> = ({
  backgroundColor = "#0a0e14",
  transparentBackground = false,
  durationInSeconds = 8,
  graphLineColor = "#f030c0",
  graphLineColor2 = "#10b981",
  gridColor = "rgba(255, 255, 255, 0.15)",
  textColor = "#8892b0",
  stickmanColor = "#000000",
  stickmanColor2 = "#10b981",
  textUp = "Guaranteed growth when the market goes up.",
  textDown = "Protection from losses when the market drops.",
  labelPink = "Stock Market",
  labelGreen = "Index Universal Life",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const totalFrames = durationInSeconds * fps;

  // Layout calculations
  const padLeft = width * 0.1;
  const padRight = width * 0.08;
  const padTop = height * 0.15;
  const padBottom = height * 0.15;
  const graphWidth = width - padLeft - padRight;
  const graphHeight = height - padTop - padBottom;

  // Map normalized points to screen coordinates
  const screenPoints1 = GRAPH_POINTS_1.map((p) => ({
    x: padLeft + p.x * graphWidth,
    y: padTop + (1 - p.y) * graphHeight,
  }));

  const screenPoints2 = GRAPH_POINTS_2.map((p) => ({
    x: padLeft + p.x * graphWidth,
    y: padTop + (1 - p.y) * graphHeight,
  }));

  // Build SVG path strings
  const pathD1 = screenPoints1
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`)
    .join(" ");

  const pathD2 = screenPoints2
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`)
    .join(" ");

  // Calculate approximate path lengths for drawing animation
  const pathLength1 = screenPoints1.reduce((acc, curr, i, arr) => {
    if (i === 0) return 0;
    const prev = arr[i - 1];
    return acc + Math.hypot(curr.x - prev.x, curr.y - prev.y);
  }, 0);

  const pathLength2 = screenPoints2.reduce((acc, curr, i, arr) => {
    if (i === 0) return 0;
    const prev = arr[i - 1];
    return acc + Math.hypot(curr.x - prev.x, curr.y - prev.y);
  }, 0);

  // Animation Timings
  const t_drawEnd = totalFrames * 0.15;
  const t_walkStart = t_drawEnd + 10;
  const t_walkEnd = totalFrames * 0.45;
  const t_slideStart = t_walkEnd;
  const t_slideEnd = totalFrames * 0.85;
  const t_standEnd = t_slideEnd + 15;

  // 1. Graph Drawing
  const drawProgress1 = interpolate(frame, [0, t_drawEnd], [0, pathLength1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.2, 0, 0, 1),
  });

  const drawProgress2 = interpolate(frame, [0, t_drawEnd], [0, pathLength2], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.2, 0, 0, 1),
  });

  // 2. Stickmen Horizontal Position X (They walk together)
  const walkEndX = screenPoints1[1].x;
  const finalX = screenPoints1[screenPoints1.length - 1].x;
  let currentX = screenPoints1[0].x;

  if (frame > t_walkStart && frame <= t_walkEnd) {
    currentX = interpolate(frame, [t_walkStart, t_walkEnd], [screenPoints1[0].x, walkEndX]);
  } else if (frame > t_slideStart) {
    currentX = interpolate(frame, [t_slideStart, t_slideEnd], [walkEndX, finalX], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.4, 0, 0.2, 1), // Accelerate then smooth stop
    });
  }

  // 3. Stickmen Vertical Positions and Slopes
  const { y: baseCurrentY1, slope: slope1 } = getPathDataAtX(currentX, screenPoints1);
  const { y: baseCurrentY2, slope: slope2 } = getPathDataAtX(currentX, screenPoints2);

  // Drop-in animation at start
  const dropProgress = spring({
    frame: frame - (t_walkStart - 15),
    fps,
    config: { damping: 12, mass: 0.8 },
  });
  const dropOffset = interpolate(dropProgress, [0, 1], [-200, 0], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  const opacity = interpolate(frame, [t_walkStart - 15, t_walkStart - 5], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  // 4. Kinematics (Angles in degrees)
  // State Blenders
  const isSliding = interpolate(frame, [t_slideStart, t_slideStart + 15], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  const isStanding = interpolate(frame, [t_slideEnd, t_standEnd], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  const blendVal = (a: number, b: number, factor: number) => a + (b - a) * factor;

  // --- STICKMAN 1: Falls and Slides ---
  const slope1Deg = (slope1 * 180) / Math.PI;
  const targetSlidePitch1 = 90 + slope1Deg; 
  let currentPitch1 = blendVal(0, targetSlidePitch1, isSliding);
  currentPitch1 = blendVal(currentPitch1, 0, isStanding);

  const walkSpeed = 0.3;
  const walkCycle = (frame - t_walkStart) * walkSpeed;
  const walkAmp = interpolate(frame, [t_walkStart, t_walkStart + 10], [0, 45], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  const poseWalk = {
    frontLeg: Math.sin(walkCycle) * -walkAmp,
    backLeg: Math.sin(walkCycle + Math.PI) * -walkAmp,
    frontArm: Math.sin(walkCycle + Math.PI) * -30,
    backArm: Math.sin(walkCycle) * -30,
    body: 5,
    offsetY: -35 + Math.abs(Math.sin(walkCycle)) * -4,
  };

  const poseSlide = {
    frontLeg: -5,
    backLeg: 5,      
    frontArm: -15,
    backArm: 15,
    body: 0,
    offsetY: -8,
  };

  const poseStand = {
    frontLeg: -5,
    backLeg: 5,
    frontArm: -10,
    backArm: 10,
    body: 0,
    offsetY: -35,
  };
  
  let currentPose1 = {
    frontLeg: blendVal(poseWalk.frontLeg, poseSlide.frontLeg, isSliding),
    backLeg: blendVal(poseWalk.backLeg, poseSlide.backLeg, isSliding),
    frontArm: blendVal(poseWalk.frontArm, poseSlide.frontArm, isSliding),
    backArm: blendVal(poseWalk.backArm, poseSlide.backArm, isSliding),
    body: blendVal(poseWalk.body, poseSlide.body, isSliding),
    offsetY: blendVal(poseWalk.offsetY, poseSlide.offsetY, isSliding),
  };

  currentPose1 = {
    frontLeg: blendVal(currentPose1.frontLeg, poseStand.frontLeg, isStanding),
    backLeg: blendVal(currentPose1.backLeg, poseStand.backLeg, isStanding),
    frontArm: blendVal(currentPose1.frontArm, poseStand.frontArm, isStanding),
    backArm: blendVal(currentPose1.backArm, poseStand.backArm, isStanding),
    body: blendVal(currentPose1.body, poseStand.body, isStanding),
    offsetY: blendVal(currentPose1.offsetY, poseStand.offsetY, isStanding),
  };

  const finalY1 = baseCurrentY1 + currentPose1.offsetY + dropOffset;

  // --- STICKMAN 2: Walks Flat then up ---
  const slope2Deg = (slope2 * 180) / Math.PI;
  const currentPitch2 = slope2Deg; // Always align rotation to current slope

  // Keep walking all the way until the stand at the very end
  const walkAmp2 = interpolate(frame, [t_walkStart, t_walkStart + 10, t_slideEnd, t_standEnd], [0, 45, 45, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const poseWalk2 = {
    frontLeg: Math.sin(walkCycle) * -walkAmp2,
    backLeg: Math.sin(walkCycle + Math.PI) * -walkAmp2,
    frontArm: Math.sin(walkCycle + Math.PI) * -30 * (walkAmp2 / 45),
    backArm: Math.sin(walkCycle) * -30 * (walkAmp2 / 45),
    body: 5 * (walkAmp2 / 45),
    offsetY: -35 + Math.abs(Math.sin(walkCycle)) * -4 * (walkAmp2 / 45),
  };

  const currentPose2 = {
    frontLeg: blendVal(poseWalk2.frontLeg, poseStand.frontLeg, isStanding),
    backLeg: blendVal(poseWalk2.backLeg, poseStand.backLeg, isStanding),
    frontArm: blendVal(poseWalk2.frontArm, poseStand.frontArm, isStanding),
    backArm: blendVal(poseWalk2.backArm, poseStand.backArm, isStanding),
    body: blendVal(poseWalk2.body, poseStand.body, isStanding),
    offsetY: blendVal(poseWalk2.offsetY, poseStand.offsetY, isStanding),
  };

  const finalY2 = baseCurrentY2 + currentPose2.offsetY + dropOffset;

  // Benefits Card Animations
  // Card 1 (Upward) Animates in after graph finishes drawing
  const card1Spring = spring({
    frame: frame - t_drawEnd,
    fps,
    config: { damping: 15, mass: 0.5 },
  });
  const card1Opacity = interpolate(frame, [t_drawEnd, t_drawEnd + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const card1TranslateY = interpolate(card1Spring, [0, 1], [40, 0]);
  const card1Scale = interpolate(card1Spring, [0, 1], [0.95, 1]);

  // Card 2 (Downward / Losses) Animates in as sliding starts
  const card2Spring = spring({
    frame: frame - t_slideStart,
    fps,
    config: { damping: 15, mass: 0.5 },
  });
  const card2Opacity = interpolate(frame, [t_slideStart, t_slideStart + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const card2TranslateY = interpolate(card2Spring, [0, 1], [40, 0]);
  const card2Scale = interpolate(card2Spring, [0, 1], [0.95, 1]);

  // Legend Animation (Fades in slightly during path drawing)
  const legendOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Graph indicator points and pulse math
  const point1X = padLeft + 0.2 * graphWidth;
  const { y: point1Y } = getPathDataAtX(point1X, screenPoints1);
  const pulseTime1 = Math.max(0, frame - t_drawEnd);
  const pulse1Radius = interpolate(pulseTime1 % 45, [0, 45], [10, 24]);
  const pulse1Opacity = frame > t_drawEnd ? interpolate(pulseTime1 % 45, [0, 45], [0.8, 0]) : 0;

  const point2X = padLeft + 0.9 * graphWidth;
  const { y: point2Y } = getPathDataAtX(point2X, screenPoints1);
  const pulseTime2 = Math.max(0, frame - t_slideStart);
  const pulse2Radius = interpolate(pulseTime2 % 45, [0, 45], [10, 24]);
  const pulse2Opacity = frame > t_slideStart ? interpolate(pulseTime2 % 45, [0, 45], [0.8, 0]) : 0;

  const point3X = padLeft + 0.9 * graphWidth;
  const { y: point3Y } = getPathDataAtX(point3X, screenPoints2);
  const pulseTime3 = Math.max(0, frame - t_slideStart);
  const pulse3Radius = interpolate(pulseTime3 % 45, [0, 45], [10, 24]);
  const pulse3Opacity = frame > t_slideStart ? interpolate(pulseTime3 % 45, [0, 45], [0.8, 0]) : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Background SVG Grid and Path */}
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0 }}>
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="8" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Grid Lines */}
        {[0, 0.5, 1].map((ratio, i) => {
          const yPos = padTop + ratio * graphHeight;
          return (
            <line
              key={`grid-${i}`}
              x1={padLeft}
              y1={yPos}
              x2={width - padRight}
              y2={yPos}
              stroke={gridColor}
              strokeWidth={2}
            />
          );
        })}

        {/* Graph Line 1 (Market drops) */}
        <path
          d={pathD1}
          fill="none"
          stroke={graphLineColor}
          strokeWidth={8}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter="url(#glow)"
          strokeDasharray={pathLength1}
          strokeDashoffset={pathLength1 - drawProgress1}
        />

        {/* Graph Line 2 (Protected Flat / Upward) */}
        <path
          d={pathD2}
          fill="none"
          stroke={graphLineColor2}
          strokeWidth={8}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter="url(#glow)"
          strokeDasharray={pathLength2}
          strokeDashoffset={pathLength2 - drawProgress2}
        />

        {/* Pulsing Graph Points */}
        {card1Opacity > 0 && (
          <g opacity={card1Opacity}>
            <circle cx={point1X} cy={point1Y} r={8} fill="#10b981" />
            <circle cx={point1X} cy={point1Y} r={pulse1Radius} fill="none" stroke="#10b981" strokeWidth={2} opacity={pulse1Opacity} />
          </g>
        )}

        {card2Opacity > 0 && (
          <g opacity={card2Opacity}>
            <circle cx={point2X} cy={point2Y} r={8} fill={graphLineColor} />
            <circle cx={point2X} cy={point2Y} r={pulse2Radius} fill="none" stroke={graphLineColor} strokeWidth={2} opacity={pulse2Opacity} />
          </g>
        )}

        {frame > t_slideStart && (
          <g opacity={interpolate(frame, [t_slideStart, t_slideStart + 15], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })}>
            <circle cx={point3X} cy={point3Y} r={8} fill={graphLineColor2} />
            <circle cx={point3X} cy={point3Y} r={pulse3Radius} fill="none" stroke={graphLineColor2} strokeWidth={2} opacity={pulse3Opacity} />
          </g>
        )}

        {/* Stickman 1 (Slides and Falls) */}
        {frame >= t_walkStart - 15 && (
          <g
            transform={`translate(${currentX}, ${finalY1}) rotate(${currentPitch1})`}
            opacity={opacity}
          >
            {/* Back Arm */}
            <g transform="translate(0, -32)">
              <Limb rotation={currentPose1.backArm} length={22} thickness={4} color={stickmanColor} />
            </g>
            
            {/* Back Leg */}
            <Limb rotation={currentPose1.backLeg} length={28} thickness={5} color={stickmanColor} />
            
            {/* Body Group (rotates from hips) */}
            <g transform={`rotate(${currentPose1.body})`}>
              {/* Torso */}
              <line
                x1={0} y1={0} x2={0} y2={-32}
                stroke={stickmanColor} strokeWidth={6} strokeLinecap="round"
              />
              {/* Head */}
              <circle cx={0} cy={-42} r={9} fill={stickmanColor} />
            </g>

            {/* Front Leg */}
            <Limb rotation={currentPose1.frontLeg} length={28} thickness={5} color={stickmanColor} />

            {/* Front Arm (Attached) */}
            <g transform="translate(0, -32)">
              <Limb rotation={currentPose1.frontArm} length={22} thickness={4} color={stickmanColor} />
            </g>
          </g>
        )}

        {/* Stickman 2 (Walks Flat then Up) */}
        {frame >= t_walkStart - 15 && (
          <g
            transform={`translate(${currentX}, ${finalY2}) rotate(${currentPitch2})`}
            opacity={opacity}
          >
            {/* Back Arm */}
            <g transform="translate(0, -32)">
              <Limb rotation={currentPose2.backArm} length={22} thickness={4} color={stickmanColor2} />
            </g>
            
            {/* Back Leg */}
            <Limb rotation={currentPose2.backLeg} length={28} thickness={5} color={stickmanColor2} />
            
            {/* Body Group (rotates from hips) */}
            <g transform={`rotate(${currentPose2.body})`}>
              {/* Torso */}
              <line
                x1={0} y1={0} x2={0} y2={-32}
                stroke={stickmanColor2} strokeWidth={6} strokeLinecap="round"
              />
              {/* Head */}
              <circle cx={0} cy={-42} r={9} fill={stickmanColor2} />
            </g>

            {/* Front Leg */}
            <Limb rotation={currentPose2.frontLeg} length={28} thickness={5} color={stickmanColor2} />

            {/* Front Arm (Attached) */}
            <g transform="translate(0, -32)">
              <Limb rotation={currentPose2.frontArm} length={22} thickness={4} color={stickmanColor2} />
            </g>
          </g>
        )}
      </svg>

      {/* HTML Text Labels */}
      {/* Y-Axis */}
      {["100%", "50%", "0"].map((label, i) => (
        <div
          key={label}
          style={{
            position: "absolute",
            left: padLeft - 24,
            top: padTop + (i * 0.5) * graphHeight,
            transform: "translate(-100%, -50%)",
            color: textColor,
            fontSize: 32,
            fontWeight: 500,
            letterSpacing: "-0.02em",
          }}
        >
          {label}
        </div>
      ))}

      {/* X-Axis */}
      <div
        style={{
          position: "absolute",
          left: padLeft,
          top: padTop + graphHeight + 32,
          transform: "translateX(-50%)",
          color: textColor,
          fontSize: 32,
          fontWeight: 500,
        }}
      >
        0:00
      </div>
      <div
        style={{
          position: "absolute",
          left: width - padRight,
          top: padTop + graphHeight + 32,
          transform: "translateX(-50%)",
          color: textColor,
          fontSize: 32,
          fontWeight: 500,
        }}
      >
        0:33
      </div>

      {/* Color Legends */}
      <div
        style={{
          position: "absolute",
          top: padTop - 50,
          right: padRight,
          display: "flex",
          gap: 40,
          opacity: legendOpacity,
          transition: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: graphLineColor }} />
          <span style={{ color: textColor, fontSize: 24, fontWeight: 600 }}>{labelPink}</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: graphLineColor2 }} />
          <span style={{ color: textColor, fontSize: 24, fontWeight: 600 }}>{labelGreen}</span>
        </div>
      </div>

      {/* Card 1: Guaranteed growth */}
      <div
        style={{
          position: "absolute",
          left: padLeft + graphWidth * 0.05,
          top: padTop + graphHeight * 0.06,
          width: width * 0.35,
          background: "rgba(255, 255, 255, 0.9)",
          backdropFilter: "blur(12px)",
          WebkitBackdropFilter: "blur(12px)",
          borderLeft: "6px solid #10b981",
          borderTop: "1px solid rgba(255, 255, 255, 0.1)",
          borderRight: "1px solid rgba(255, 255, 255, 0.05)",
          borderBottom: "1px solid rgba(255, 255, 255, 0.05)",
          borderRadius: "0px 16px 16px 0px",
          padding: "24px 32px",
          opacity: card1Opacity,
          transform: `translateY(${card1TranslateY}px) scale(${card1Scale})`,
          transformOrigin: "left center",
          display: "flex",
          flexDirection: "column",
          gap: 8,
          boxShadow: "0 20px 50px rgba(0, 0, 0, 0.3)",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <div style={{ color: "#10b981", fontSize: 20, fontWeight: 700, letterSpacing: 2, textTransform: "uppercase" }}>
          Upward Market
        </div>
        <div style={{ color: "#000000", fontSize: 30, fontWeight: 600, lineHeight: 1.3 }}>
          {textUp}
        </div>
      </div>

      {/* Card 2: Protection from losses */}
      <div
        style={{
          position: "absolute",
          left: padLeft + graphWidth * 0.52,
          top: padTop + graphHeight * 0.45,
          width: width * 0.38,
          background: "rgba(255, 255, 255, 0.9)",
          backdropFilter: "blur(12px)",
          WebkitBackdropFilter: "blur(12px)",
          borderLeft: `6px solid ${graphLineColor}`,
          borderTop: "1px solid rgba(255, 255, 255, 0.1)",
          borderRight: "1px solid rgba(255, 255, 255, 0.05)",
          borderBottom: "1px solid rgba(255, 255, 255, 0.05)",
          borderRadius: "0px 16px 16px 0px",
          padding: "24px 32px",
          opacity: card2Opacity,
          transform: `translateY(${card2TranslateY}px) scale(${card2Scale})`,
          transformOrigin: "left center",
          display: "flex",
          flexDirection: "column",
          gap: 8,
          boxShadow: "0 20px 50px rgba(0, 0, 0, 0.3)",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <div style={{ color: graphLineColor, fontSize: 20, fontWeight: 700, letterSpacing: 2, textTransform: "uppercase" }}>
          Downward Market
        </div>
        <div style={{ color: "#000000", fontSize: 30, fontWeight: 600, lineHeight: 1.3 }}>
          {textDown}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GraphWalk;